parameters.jsonBody:
={
  "model": "sonar",
  "messages": [{"role": "user", "content": "What is the sentiment of tech media (TechCrunch, Wired, The Verge, Ars Technica) toward {{ $json.specific_brands }} this week? What stories ran, what tone was used, any controversies?"}],
  "search_recency_filter": "week"
}

={
  "model": "sonar",
  "messages": [{"role": "user", "content": "What is the sentiment of business and financial media (Bloomberg, Forbes, WSJ, FT, Economic Times) toward {{ $json.entity }} this week? How are investors and analysts viewing the space?"}],
  "search_recency_filter": "week"
}

={
  "model": "sonar",
  "messages": [{"role": "user", "content": "What is the social media and developer community sentiment toward {{ $json.specific_brands }} this week on Twitter/X, LinkedIn, Hacker News, and Reddit? Any viral posts, controversies, or strong community reactions?"}],
  "search_recency_filter": "week"
}

parameters.text:
=Synthesize this week's media sentiment data into a comprehensive tracking report.

Entity: {{ $('Set Tracking Config').item.json.entity }}
Brands: {{ $('Set Tracking Config').item.json.specific_brands }}

Tech Media Sentiment:
{{ $('Scan Tech Media').item.json.choices[0].message.content }}

Business Media Sentiment:
{{ $('Scan Business Media').item.json.choices[0].message.content }}

Social Signals:
{{ $('Scan Social Signals').item.json.choices[0].message.content }}

Return JSON:
{
  "overall_sentiment": "very positive/positive/neutral/negative/very negative",
  "sentiment_score": 0,
  "brand_sentiments": [{"brand": "", "sentiment": "", "key_story": ""}],
  "narrative_shifts": [],
  "positive_stories": [],
  "negative_stories": [],
  "viral_moments": [],
  "media_coverage_volume": "high/medium/low",
  "week_over_week_change": "improving/stable/declining",
  "reputational_risks": [],
  "weekly_narrative": "3-4 sentence summary of the week's media story"
}

=📡 *Weekly Media Sentiment Report*

*Overall:* {{ $json.overall_sentiment }} ({{ $json.sentiment_score }}/10)
*Trend:* {{ $json.week_over_week_change }}

{{ $json.weekly_narrative }}

*Brand Sentiments:*
{{ $json.brand_sentiments.map(b=>`• ${b.brand}: ${b.sentiment}`).join('\n') }}

*Viral Moments:* {{ $json.viral_moments.join(', ') || 'None this week' }}
*Reputational Risks:* {{ $json.reputational_risks.join(', ') || 'None' }}
